WITH base AS (SELECT * FROM products WHERE product_name IS NOT NULL), products_stats AS (SELECT brand, CASE WHEN cost >= 700 THEN 'high' WHEN cost >= 250 THEN 'mid' ELSE 'low' END AS cost_bucket, COUNT(cost) AS cost_count, AVG(price) AS avg_price FROM base GROUP BY brand, CASE WHEN cost >= 700 THEN 'high' WHEN cost >= 250 THEN 'mid' ELSE 'low' END) SELECT brand, cost_bucket, cost_count, avg_price FROM products_stats WHERE avg_price > 890 ORDER BY cost_bucket DESC, cost_count DESC
